#!/usr/bin/env sh
# Creates .env with fresh random secrets if it doesn't exist yet. Never commit .env.
set -eu
cd "$(dirname "$0")/.."

if [ -f .env ]; then
  echo ".env already exists; leaving it alone."
  exit 0
fi

rand() { head -c 32 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c "$1"; }

admin_password="$(rand 20)"
cat > .env <<ENV
# Generated by scripts/init-env.sh. Keep this file private.
POSTGRES_PASSWORD=$(rand 32)
KATRA_HTTPS_PORT=8443

# First staff account, created on first start when the database is empty.
KATRA_BOOTSTRAP_ADMIN_EMAIL=admin@example.com
KATRA_BOOTSTRAP_ADMIN_PASSWORD=${admin_password}

# "fake" runs fully offline. Real providers arrive in M3 (embeddings) and M4 (LLM).
KATRA_LLM_PROVIDER=fake
KATRA_EMBEDDING_PROVIDER=fake
ANTHROPIC_API_KEY=
ENV
chmod 600 .env

echo "Created .env"
echo "  Admin login: admin@example.com / ${admin_password}"
